package in.kabadiwala.connect.service.impl; import in.kabadiwala.connect.dto.AuthDtos.*;import in.kabadiwala.connect.integration.SmsProvider;import in.kabadiwala.connect.model.*;import in.kabadiwala.connect.repository.*;import in.kabadiwala.connect.security.JwtService;import in.kabadiwala.connect.service.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import java.time.*;import java.security.*;import java.nio.charset.StandardCharsets;import java.util.*;
@Service public class AuthServiceImpl implements AuthService {private final UserRepository users;private final OtpVerificationRepository otps;private final RefreshTokenRepository refresh;private final RecyclerProfileRepository recyclers;private final CollectorProfileRepository collectors;private final PasswordEncoder enc;private final JwtService jwt;private final SmsProvider sms;private final AuditService audit;private final SecureRandom random=new SecureRandom();private final long refreshDays;public AuthServiceImpl(UserRepository u,OtpVerificationRepository o,RefreshTokenRepository rt,RecyclerProfileRepository rp,CollectorProfileRepository cp,PasswordEncoder e,JwtService j,SmsProvider sms,AuditService a,@Value("${app.jwt-refresh-days:14}")long d){users=u;otps=o;refresh=rt;recyclers=rp;collectors=cp;enc=e;jwt=j;this.sms=sms;audit=a;refreshDays=d;}private String hash(String x){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(x.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} public String sendOtp(OtpRequest r){String purpose=r.purpose().toUpperCase();if(!Set.of("REGISTER","RESET").contains(purpose))throw new IllegalArgumentException("Invalid OTP purpose");var prev=otps.findTopByMobileAndPurposeOrderByLastSentAtDesc(r.mobile(),purpose).orElse(null);if(prev!=null&&prev.lastSentAt.isAfter(Instant.now().minusSeconds(30)))throw new IllegalArgumentException("Please wait before requesting another OTP");String code=String.format("%06d",random.nextInt(1_000_000));var o=new OtpVerification();o.mobile=r.mobile();o.purpose=purpose;o.otpHash=enc.encode(code);o.expiresAt=Instant.now().plusSeconds(300);o.lastSentAt=Instant.now();otps.save(o);sms.sendOtp(r.mobile(),code,"hi");return sms.exposesDevelopmentCode()?code:null;} public void verifyOtp(OtpVerify r){var o=otps.findTopByMobileAndPurposeOrderByLastSentAtDesc(r.mobile(),r.purpose().toUpperCase()).orElseThrow(()->new IllegalArgumentException("OTP not found"));if(o.verified)throw new IllegalArgumentException("OTP already used");if(o.expiresAt.isBefore(Instant.now()))throw new IllegalArgumentException("OTP expired");if(o.attempts>=5)throw new IllegalArgumentException("Too many attempts");o.attempts++;if(!enc.matches(r.otp(),o.otpHash)){otps.save(o);throw new IllegalArgumentException("Invalid OTP");}o.verified=true;otps.save(o);} public Token register(Register r){if(r.role()==Role.ADMIN)throw new IllegalArgumentException("Admin registration is not public");if(users.findByMobile(r.mobile()).isPresent())throw new IllegalArgumentException("Mobile already registered");var o=otps.findTopByMobileAndPurposeOrderByLastSentAtDesc(r.mobile(),"REGISTER").orElseThrow(()->new IllegalArgumentException("Verify mobile first"));if(!o.verified)throw new IllegalArgumentException("Verify mobile first");var u=new User();u.fullName=r.fullName();u.mobile=r.mobile();u.email=r.email();u.passwordHash=enc.encode(r.password());u.language=r.language()==null?"hi":r.language();u.role=r.role()==null?Role.COLLECTOR:r.role();u.mobileVerified=true;u.recyclerStatus=u.role==Role.RECYCLER?"PENDING_VERIFICATION":null;users.save(u);if(u.role==Role.RECYCLER){var p=new RecyclerProfile();p.userId=u.id;p.businessName=r.businessName();p.authorizedPerson=r.fullName();p.address=r.address();p.city=r.city();p.state=r.state();p.pincode=r.pincode();p.licenseNumber=r.licenseNumber();recyclers.save(p);}else{var p=new CollectorProfile();p.userId=u.id;p.address=r.address();p.city=r.city();p.state=r.state();p.pincode=r.pincode();collectors.save(p);}audit.log(u.id,"REGISTER","USER",u.id,null,u.role.name(),Map.of());return tokens(u);} public Token login(Login r){var u=users.findByMobile(r.mobile()).orElse(null);if(u==null||!enc.matches(r.password(),u.passwordHash)){audit.log(u==null?"anonymous":u.id,"LOGIN_FAILED","USER",u==null?r.mobile():u.id,null,null,Map.of());throw new IllegalArgumentException("Invalid credentials");}audit.log(u.id,"LOGIN","USER",u.id,null,null,Map.of());return tokens(u);} private Token tokens(User u){String raw=Base64.getUrlEncoder().withoutPadding().encodeToString(random.generateSeed(48));var rt=new RefreshToken();rt.userId=u.id;rt.tokenHash=hash(raw);rt.expiresAt=Instant.now().plus(Duration.ofDays(refreshDays));refresh.save(rt);return new Token(jwt.issue(u.id,u.role.name()),raw,jwt.expirySeconds(),u.role.name(),u.fullName);} public Token refresh(String raw){var old=refresh.findByTokenHash(hash(raw)).orElseThrow(()->new IllegalArgumentException("Invalid refresh token"));if(old.revoked||old.expiresAt.isBefore(Instant.now()))throw new IllegalArgumentException("Refresh token expired or revoked");old.revoked=true;var u=users.findById(old.userId).orElseThrow();var t=tokens(u);old.replacedByHash=hash(t.refreshToken());refresh.save(old);return t;}public void logout(String uid,String raw){refresh.findByTokenHash(hash(raw)).filter(x->x.userId.equals(uid)).ifPresent(x->{x.revoked=true;refresh.save(x);});audit.log(uid,"LOGOUT","USER",uid,null,null,Map.of());}public void resetPassword(String mobile,String otp,String p){verifyOtp(new OtpVerify(mobile,otp,"RESET"));var u=users.findByMobile(mobile).orElseThrow(()->new IllegalArgumentException("User not found"));u.passwordHash=enc.encode(p);users.save(u);refresh.findByUserIdAndRevokedFalse(u.id).forEach(x->{x.revoked=true;refresh.save(x);});audit.log(u.id,"PASSWORD_RESET","USER",u.id,null,null,Map.of());}}
